import { createPinia, disposePinia } from 'pinia';
import { createApp } from 'vue';
import App from './app.vue';
import { getFrontendRevision } from './frontend-revision';
import { PSEUDO_LAYER_DETACHED_STORAGE_KEY } from './pseudo-layer-protocol';

$(() => {
  let disposed = false;
  let unmount: (() => void) | undefined;
  let controllerFallbackTimer: number | null = null;
  let controllerFallbackExpired = false;
  const frame = window.frameElement as HTMLIFrameElement | null;
  const parentWindow = window.parent as Window & { __dhlPseudoLayerControllerLease__?: unknown };
  const parentBody = parentWindow.document.body;

  const isDetachedPreferred = () => {
    try {
      return localStorage.getItem(PSEUDO_LAYER_DETACHED_STORAGE_KEY) === 'true';
    } catch {
      return false;
    }
  };

  const computeShouldMount = () => {
    if (frame?.dataset.dhlControllerOwned === 'true') return true;
    if (parentBody.classList.contains('dhl-pseudo-stage-root-active')) return false;
    if (isDetachedPreferred()) return true;
    const hasController =
      Boolean(parentWindow.__dhlPseudoLayerControllerLease__) ||
      parentBody.classList.contains('dhl-pseudo-layer-active');
    if (hasController) {
      // 切回伪同层过渡期仅当当前原生楼层已挂载时短暂保留显示，待自有舞台就绪后立即卸载释放内存。
      return Boolean(unmount);
    }
    return controllerFallbackExpired;
  };

  const syncMount = () => {
    if (disposed) return;
    const shouldMount = computeShouldMount();
    if (!shouldMount) {
      unmount?.();
      unmount = undefined;
      return;
    }
    if (unmount) return;
    const pinia = createPinia();
    const app = createApp(App);
    app.use(pinia);
    app.mount('#app');
    unmount = () => {
      app.unmount();
      disposePinia(pinia);
    };
  };

  if (frame?.dataset.dhlControllerOwned !== 'true' && !isDetachedPreferred()) {
    controllerFallbackTimer = window.setTimeout(() => {
      controllerFallbackTimer = null;
      controllerFallbackExpired = true;
      syncMount();
    }, 1500);
  }

  const observer = new MutationObserver(syncMount);
  observer.observe(parentBody, { attributes: true, attributeFilter: ['class'] });
  const onStorage = (event: StorageEvent) => {
    if (!event.key || event.key === PSEUDO_LAYER_DETACHED_STORAGE_KEY) syncMount();
  };
  parentWindow.addEventListener('storage', onStorage);
  syncMount();
  // 原生楼层在舞台启用时只运行加载器，也要把新编译版本交给控制器。
  const revision = getFrontendRevision(document);
  if (frame && revision) frame.dataset.dhlFrontendRevision = revision;

  const dispose = () => {
    if (disposed) return;
    disposed = true;
    if (controllerFallbackTimer !== null) {
      window.clearTimeout(controllerFallbackTimer);
      controllerFallbackTimer = null;
    }
    parentWindow.removeEventListener('storage', onStorage);
    observer.disconnect();
    unmount?.();
    unmount = undefined;
  };
  window.addEventListener('pagehide', dispose, { once: true });
});
